INSERT INTO `conversation_messages` VALUES ('2026-06-26 09:10:58.687176','2026-06-26 09:10:58.687176',NULL,18,326,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','user','je veux creer un dossier comment faire ?',NULL,10,NULL,NULL,NULL),('2026-06-26 09:11:25.655736','2026-06-26 09:11:25.655736',NULL,18,327,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','assistant','📁 **Aucun dossier trouvé correspondant à votre recherche.**\n\nCela peut être dû à :\n- Un numéro de dossier inexistant\n- Des critères de recherche trop restrictifs\n- Un dossier récemment archivé\n\n💡 **Recommandation :** Vérifiez le numéro de dossier ou élargissez vos critères de recherche.',NULL,73,NULL,NULL,'{\"sqlQuery\":\"SELECT \'La création de dossier via SQL est interdite. Voici les champs obligatoires pour un dossier : dossier_number, object, jurisdiction_id, danger_level, status, opening_date, client_id, lawyer_id, procedure_type_id, procedure_subtype_id, tenant_id (18).\' AS message WHERE 1=0 LIMIT 50\",\"results\":[],\"rowCount\":0}'),('2026-06-26 10:20:26.220586','2026-06-26 10:20:26.220586',NULL,18,328,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','user','je veux creer un dossier comment faire ?',NULL,10,NULL,NULL,NULL),('2026-06-26 10:20:26.244075','2026-06-26 10:20:26.244075',NULL,18,329,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','assistant','Pour créer un dossier :\n\n1. Ouvrez le module Dossiers.\n2. Cliquez sur Nouveau dossier.\n3. Sélectionnez ou créez le client concerné.\n4. Renseignez la procédure, l\'objet du litige, la partie adverse et les dates importantes.\n5. Ajoutez les documents si nécessaire.\n6. Cliquez sur Enregistrer.\n\nSi vous voulez, je peux aussi créer le dossier pour vous si vous me donnez les informations nécessaires.',NULL,99,NULL,NULL,NULL),('2026-06-26 10:21:13.339414','2026-06-26 10:21:13.339414',NULL,18,330,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','user','je veux creer un document comment faire ?',NULL,11,NULL,NULL,NULL),('2026-06-26 10:21:13.361931','2026-06-26 10:21:13.361931',NULL,18,331,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','assistant','Je peux vous guider dans l\'utilisation de l\'application.\n\nPrécisez le module ou l\'action qui vous intéresse, par exemple : créer un dossier, créer un client, ajouter une audience ou enregistrer un paiement.',NULL,52,NULL,NULL,NULL),('2026-06-26 10:22:04.042749','2026-06-26 10:22:04.042749',NULL,18,332,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','user','créer un clien',NULL,4,NULL,NULL,NULL),('2026-06-26 10:22:04.124371','2026-06-26 10:22:04.124371',NULL,18,333,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','assistant','⚠️ **Confirmation requise**\n\n**Plan d\'opérations à confirmer :**\n\n📋 **Description:** Créer un nouveau client (informations manquantes : nom, prénom, code client)\n\n**Confiance:** 30%\n\n**Opérations prévues:**\n1. ➕ **INSERT** sur **customer**\n   📝 Champs: \"last_name\", \"first_name\", \"customer_code\"\n   🔗 Référencé comme: **new_client**\n\n\n---\n⚠️ **Voulez-vous confirmer cette opération ?**\n✅ Confirmer | ❌ Annuler',NULL,103,NULL,NULL,'{\"pendingWritePlan\":{\"transaction\":true,\"operations\":[{\"operation\":\"INSERT\",\"entity\":\"customer\",\"entityId\":null,\"fields\":{\"last_name\":\"\",\"first_name\":\"\",\"customer_code\":\"\"},\"tempId\":\"new_client\",\"dependsOn\":[]}],\"humanReadable\":\"Créer un nouveau client (informations manquantes : nom, prénom, code client)\",\"confidence\":0.3},\"requiresConfirmation\":true}'),('2026-06-26 11:49:05.728137','2026-06-26 11:49:05.728137',NULL,18,334,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','user','créer un client',NULL,4,NULL,NULL,NULL),('2026-06-26 12:48:39.132987','2026-06-26 12:48:39.132987',NULL,18,335,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','user','créer un client',NULL,4,NULL,NULL,NULL),('2026-06-26 12:48:39.145023','2026-06-26 12:48:39.145023',NULL,18,336,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','assistant','⚠️ **Confirmation requise**\n\n**Plan d\'opérations à confirmer :**\n\n📋 **Description:** Créer un nouveau client (informations manquantes : nom, prénom, code client)\n\n**Confiance:** 30%\n\n**Opérations prévues:**\n1. ➕ **INSERT** sur **customer**\n   📝 Champs: \"last_name\", \"first_name\", \"customer_code\"\n   🔗 Référencé comme: **new_client**\n\n\n---\n⚠️ **Voulez-vous confirmer cette opération ?**\n✅ Confirmer | ❌ Annuler',NULL,103,NULL,NULL,'{\"pendingWritePlan\":{\"transaction\":true,\"operations\":[{\"operation\":\"INSERT\",\"entity\":\"customer\",\"entityId\":null,\"fields\":{\"last_name\":\"\",\"first_name\":\"\",\"customer_code\":\"\"},\"tempId\":\"new_client\",\"dependsOn\":[]}],\"humanReadable\":\"Créer un nouveau client (informations manquantes : nom, prénom, code client)\",\"confidence\":0.3},\"requiresConfirmation\":true}'),('2026-06-26 12:50:23.569689','2026-06-26 12:50:23.569689',NULL,18,337,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','user','liste les juridictions du cabinet',NULL,9,NULL,NULL,NULL),('2026-06-26 12:51:17.690710','2026-06-26 12:51:17.690710',NULL,18,338,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','assistant','Voici la liste des juridictions auprès desquelles le cabinet intervient :\n\n**Juridictions nationales :**\n* Cour d\'Appel de Douala (ID: 110) - Commercial\n* Cour d\'Appel de Yaoundé (ID: 109) - Civil\n* Cour Suprême du Cameroun (ID: 114) - Administratif\n\n**Juridictions régionales :**\n* Tribunal de Commerce de Douala (ID: 111) - Commercial\n* Tribunal pour Enfants de Yaoundé (ID: 113) - Familial\n* Tribunal de Première Instance de Bamenda (ID',NULL,110,NULL,NULL,'{\"sqlQuery\":\"SELECT j.id, j.code, j.name, j.level, j.jurisdiction_type, j.city, j.is_active \\nFROM jurisdictions j \\nWHERE j.tenant_id = 18 AND j.deleted_at IS NULL \\nLIMIT 50\",\"results\":[{\"id\":110,\"code\":\"CA_DOUALA\",\"name\":\"Cour d\'Appel de Douala\",\"level\":\"national\",\"jurisdiction_type\":\"commercial\",\"city\":\"Douala\",\"is_active\":1},{\"id\":109,\"code\":\"CA_YAOUNDE\",\"name\":\"Cour d\'Appel de Yaoundé\",\"level\":\"national\",\"jurisdiction_type\":\"civil\",\"city\":\"Yaoundé\",\"is_active\":1},{\"id\":114,\"code\":\"COUR_SUPREME\",\"name\":\"Cour Suprême du Cameroun\",\"level\":\"national\",\"jurisdiction_type\":\"administrative\",\"city\":\"Yaoundé\",\"is_active\":1},{\"id\":111,\"code\":\"TC_DOUALA\",\"name\":\"Tribunal de Commerce de Douala\",\"level\":\"regional\",\"jurisdiction_type\":\"commercial\",\"city\":\"Douala\",\"is_active\":1},{\"id\":113,\"code\":\"TE_YAOUNDE\",\"name\":\"Tribunal pour Enfants de Yaoundé\",\"level\":\"regional\",\"jurisdiction_type\":\"family\",\"city\":\"Yaoundé\",\"is_active\":1},{\"id\":108,\"code\":\"TPI_BAMENDA\",\"name\":\"Tribunal de Première Instance de Bamenda\",\"level\":\"regional\",\"jurisdiction_type\":\"civil\",\"city\":\"Bamenda\",\"is_active\":1},{\"id\":107,\"code\":\"TPI_DOUALA\",\"name\":\"Tribunal de Première Instance de Douala\",\"level\":\"regional\",\"jurisdiction_type\":\"commercial\",\"city\":\"Douala\",\"is_active\":1},{\"id\":106,\"code\":\"TPI_YAOUNDE\",\"name\":\"Tribunal de Première Instance de Yaoundé\",\"level\":\"regional\",\"jurisdiction_type\":\"civil\",\"city\":\"Yaoundé\",\"is_active\":1},{\"id\":112,\"code\":\"TT_YAOUNDE\",\"name\":\"Tribunal du Travail de Yaoundé\",\"level\":\"regional\",\"jurisdiction_type\":\"labor\",\"city\":\"Yaoundé\",\"is_active\":1}],\"rowCount\":9}'),('2026-06-26 12:53:06.211360','2026-06-26 12:53:06.211360',NULL,18,339,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','user','quelles sont les news concernant le domaine juridique ?',NULL,14,NULL,NULL,NULL),('2026-06-26 12:53:17.315383','2026-06-26 12:53:17.315383',NULL,18,340,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','assistant','ℹ️ **Aucun résultat trouvé** pour votre question.\n\nVérifiez les informations saisies ou reformulez votre demande avec plus de précision.',NULL,34,NULL,NULL,'{\"sqlQuery\":\"SELECT NULL AS message WHERE 1=0\",\"results\":[],\"rowCount\":0}'),('2026-06-26 18:03:15.300783','2026-06-26 18:03:15.300783',NULL,18,341,'7702f37d-29ef-4b02-ba34-50ba3eac0bb3','user','quelles sont les n