INSERT INTO `mail_templates` VALUES ('2026-06-26 08:48:26.382096','2026-06-26 08:48:26.382096',NULL,18,548,'account_activation','Activation de compte','auth','collaborator','Envoye pour activer un compte collaborateur nouvellement cree.','Activez votre compte {{cabinetName}}','\n<h2 style=\"margin:0 0 12px;color:#111827;\">Activation de compte</h2>\n<p>Bonjour {{firstName}},</p>\n<p>Votre compte collaborateur a ete cree sur l\'espace <strong>{{cabinetName}}</strong>.</p>\n<p style=\"text-align:center;margin:28px 0;\">\n  <a href=\"{{activationUrl}}\" style=\"background:{{brandColor}};color:#ffffff;text-decoration:none;padding:12px 22px;border-radius:5px;font-weight:600;display:inline-block;\">Activer mon compte</a>\n</p>\n<p style=\"color:#6b7280;font-size:13px;\">L\'activation vous permettra de definir votre mot de passe et d\'acceder a votre espace de travail.</p>','[\"firstName\",\"activationUrl\",\"cabinetName\",\"brandColor\"]',NULL,NULL,NULL,1,1),('2026-06-26 08:48:26.367763','2026-06-26 08:48:26.367763',NULL,18,546,'account_opening','Ouverture de compte','auth','both','Envoye lorsqu\'un compte est ouvert ou qu\'un utilisateur doit definir son acces.','Votre acces {{cabinetName}} est pret','\n<h2 style=\"margin:0 0 12px;color:#111827;\">Bienvenue {{firstName}}</h2>\n<p>Un acces a ete cree pour vous sur l\'espace <strong>{{cabinetName}}</strong>.</p>\n<p>Utilisez le bouton ci-dessous pour vous connecter ou finaliser la creation de votre mot de passe.</p>\n<p style=\"text-align:center;margin:28px 0;\">\n  <a href=\"{{loginUrl}}\" style=\"background:{{brandColor}};color:#ffffff;text-decoration:none;padding:12px 22px;border-radius:5px;font-weight:600;display:inline-block;\">Acceder a mon espace</a>\n</p>\n<p style=\"color:#6b7280;font-size:13px;\">Si vous n\'attendiez pas cet acces, vous pouvez ignorer ce message ou contacter le cabinet.</p>\n<p>Cordialement,<br/><strong>{{cabinetName}}</strong></p>','[\"firstName\",\"loginUrl\",\"cabinetName\",\"brandColor\"]',NULL,NULL,NULL,1,1),('2026-06-26 08:48:26.470310','2026-06-26 08:48:26.470310',NULL,18,565,'audience_created_client','Audience creee - client','audience','client','Modele systeme modifiable pour les notifications client.','Audience du {{audience.date}} - dossier {{dossier.numero}}','\n<h2 style=\"margin:0 0 12px;color:#111827;\">Audience du {{audience.date}} - dossier {{dossier.numero}}</h2>\n<p>Bonjour{{#if client.nom}} {{client.nom}}{{/if}},</p>\n<p>Une audience a ete planifiee dans votre dossier. Merci de prendre connaissance des informations pratiques.</p>\n\n<table style=\"width:100%;border-collapse:collapse;margin:18px 0;font-size:13px;\">\n{{#if dossier.numero}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Dossier</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.numero}}</td>\n  </tr>\n{{/if}}\n{{#if dossier.objet}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Objet</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.objet}}</td>\n  </tr>\n{{/if}}\n{{#if client.nom}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Client</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{client.nom}}</td>\n  </tr>\n{{/if}}\n{{#if dossier.statut}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Statut dossier</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.statut}}</td>\n  </tr>\n{{/if}}\n{{#if dossier.etape}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Etape</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.etape}}</td>\n  </tr>\n{{/if}}\n{{#if dossier.juridiction}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Juridiction</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.juridiction}}</td>\n  </tr>\n{{