ction}}</td>\n  </tr>\n{{/if}}\n{{#if dossier.avocat}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Avocat responsable</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.avocat}}</td>\n  </tr>\n{{/if}}\n</table>\n{{#if link}}\n<p style=\"text-align:center;margin:22px 0;\">\n  <a href=\"{{link}}\" style=\"background:#111827;color:#ffffff;text-decoration:none;padding:11px 18px;border-radius:5px;font-weight:600;display:inline-block;\">Voir le paiement</a>\n</p>\n{{/if}}\n<p style=\"color:#6b7280;font-size:12px;margin-top:18px;\">Notification interne envoyee automatiquement par {{cabinet.nom}} le {{date.aujourdhui}}.</p>','[\"link\",\"brandColor\",\"cabinet.nom\",\"cabinet.email\",\"cabinet.telephone\",\"date.aujourdhui\",\"dossier.numero\",\"dossier.objet\",\"dossier.description\",\"dossier.statut\",\"dossier.etape\",\"dossier.date_ouverture\",\"dossier.juridiction\",\"dossier.partie_adverse\",\"dossier.avocat\",\"client.nom\",\"client.email\",\"client.telephone\",\"facture.numero\",\"facture.date\",\"facture.echeance\",\"facture.montant_ttc\",\"facture.montant_paye\",\"facture.reste_a_payer\",\"facture.statut\",\"facture.type\",\"paiement.reference\",\"paiement.montant\",\"paiement.date\",\"paiement.mode\",\"paiement.statut\"]',NULL,NULL,NULL,1,1),('2026-06-26 08:48:26.399388','2026-06-26 08:48:26.399388',NULL,18,552,'password_changed','Mot de passe modifie','auth','both','Confirmation envoyee apres un changement de mot de passe reussi.','Votre mot de passe a ete modifie','\n<h2 style=\"margin:0 0 12px;color:#111827;\">Mot de passe modifie</h2>\n<p>Bonjour {{firstName}},</p>\n<p>Nous vous confirmons que votre mot de passe a bien ete modifie{{#if changedAt}} le {{changedAt}}{{/if}}.</p>\n<p style=\"color:#b91c1c;font-size:13px;\">Si vous n\'etes pas a l\'origine de cette operation, contactez immediatement {{cabinetName}}.</p>','[\"firstName\",\"changedAt\",\"cabinetName\",\"brandColor\"]',NULL,NULL,NULL,1,1),('2026-06-26 08:48:26.601943','2026-06-26 08:48:26.601943',NULL,18,591,'procedure_stage_changed_client','Etape de procedure modifiee - client','dossier','client','Modele systeme modifiable pour les notifications client.','Nouvelle etape - dossier {{dossier.numero}}','\n<h2 style=\"margin:0 0 12px;color:#111827;\">Nouvelle etape - dossier {{dossier.numero}}</h2>\n<p>Bonjour{{#if client.nom}} {{client.nom}}{{/if}},</p>\n<p>Votre dossier a avance vers une nouvelle etape de procedure.</p>\n\n<table style=\"width:100%;border-collapse:collapse;margin:18px 0;font-size:13px;\">\n{{#if dossier.numero}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Dossier</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.numero}}</td>\n  </tr>\n{{/if}}\n{{#if dossier.objet}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Objet</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.objet}}</td>\n  </tr>\n{{/if}}\n{{#if client.nom}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Client</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{client.nom}}</td>\n  </tr>\n{{/if}}\n{{#if dossier.statut}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Statut dossier</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.statut}}</td>\n  </tr>\n{{/if}}\n{{#if dossier.etape}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Etape</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.etape}}</td>\n  </tr>\n{{/if}}\n{{#if dossier.juridiction}}\n  <tr>\n    <td style=\"padding:8px 10px;background:#f3f4f6;font-weight:600;width:38%;\">Juridiction</td>\n    <td style=\"padding:8px 10px;background:#f9fafb;\">{{dossier.juridiction}}</td>\n  </tr>\n{{/if}}\n{{#if dossier.avocat}}\n  <tr>\n    <td style=\"padding:8px 10px